{async () => {
              try {
                await fetchJSON("/api/m365/planner/tasks", {
                  method: "POST",
                  headers: { "Content-Type": "application/json" },
                  body: JSON.stringify({ title, notes, due_date: due, entity_type, entity_id }),
                });
                onClose();
              } catch (error) {
                alert(error.message);
              }
            }}

{(e) => {
                          const newToken = e.target.value;
                          changeAdminToken(newToken);
                          // Persist to localStorage
                          try {
                            if (newToken) {
                              localStorage.setItem('ecc-admin-token', newToken);
                            } else {
                              localStorage.removeItem('ecc-admin-token');
                            }
                          } catch (err) {
                            console.warn('Failed to save admin token to localStorage:', err);
                          }
                        }}

{() => {
                  if (window.confirm(`Are you sure you want to delete all ${filteredItems.length} items? This cannot be undone.`)) {
                    clearAllMutation.mutate();
                  }
                }}

{async () => {
            if (!property?.id) return;
            try {
              setWoBusy(true);
              const r = await createWorkOrder({ 
                propertyId: String(property.id), 
                summary: `WO from Property #${property.id}`, 
                priority: 'normal' 
              });
              (window as any).toast?.success?.('Work order created') ?? alert('Work order created');
              console.log('WO:', r);
            } catch (e:any) {
              (window as any).toast?.error?.('Failed to create work order') ?? alert('Failed to create work order');
              console.error(e);
            } finally {
              setWoBusy(false);
            }
          }}
